css:
.d1118-sig{stroke-dasharray:160;animation:d1118-draw 3.6s ease-in-out infinite}
.d1118-pen,.d1118-toe,.d1118-rip{transform-box:fill-box}
.d1118-pen{animation:d1118-pen 3.6s ease-in-out infinite}
.d1118-ok{transform-box:fill-box;transform-origin:center;animation:d1118-stamp 3.6s ease-in infinite}
.d1118-toe{transform-origin:center top;animation:d1118-dip 3.4s ease-in-out infinite}
.d1118-rip{transform-origin:center;animation:d1118-rip 3.4s ease-out infinite}
@keyframes d1118-draw{0%{stroke-dashoffset:160}50%,100%{stroke-dashoffset:0}}
@keyframes d1118-pen{0%{transform:translate(-76px,0)}50%{transform:translate(0,0)}100%{transform:translate(0,0)}}
@keyframes d1118-stamp{0%,55%{opacity:0;transform:scale(1.6)}70%,100%{opacity:1;transform:scale(1)}}
@keyframes d1118-dip{0%,100%{transform:translateY(-12px)}45%,60%{transform:translateY(6px)}}
@keyframes d1118-rip{0%,40%{opacity:0;transform:scale(.4)}55%{opacity:1;transform:scale(1)}100%{opacity:0;transform:scale(1.8)}}
@media (prefers-reduced-motion:reduce){.d1118-sig{stroke-dasharray:none}.d1118-ok{opacity:1}.d1118-rip{opacity:1}}
